import assert from 'node:assert/strict';
import crypto, {createHash, randomBytes} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const A = await import('./packages/engine-adapter/dist/index.js');
const R = await import('./packages/engine-adapter/dist/replay.js');
const {ENGINE_REPLAY_IDENTITY} = await import('./packages/engine-adapter/dist/code-identity.js');
assert.deepEqual(Object.keys(A).sort(), ['ENGINE_QUALIFICATION', 'assessEngineAdmission', 'createQualificationMatch', 'verifyCompletedReplay']);
const RealDate = Date, realRandom = Math.random, realUUID = crypto.randomUUID, realGRV = globalThis.crypto.getRandomValues;
const forbid = name => () => { throw new Error('ambient ' + name); };
function disableAmbient() {
  Math.random = forbid('Math.random'); crypto.randomUUID = forbid('randomUUID'); globalThis.crypto.getRandomValues = forbid('getRandomValues');
  globalThis.Date = class extends RealDate { constructor(...a) { if (!a.length) throw new Error('ambient new Date()'); super(...a); } static now() { throw new Error('ambient Date.now'); } };
}
function restoreAmbient() { Math.random = realRandom; crypto.randomUUID = realUUID; globalThis.crypto.getRandomValues = realGRV; globalThis.Date = RealDate; }
let n = 0;
const cmd = (m, actor, move, input = {}, timestamp = 1000 + n) => ({actor, move, input, timestamp, expectedRevision: m.status().revision, commandId: 'c' + (n++)});
const digest = archive => createHash('sha256').update('completed-private-replay-v1\0').update(archive).digest('hex');
function play(m, loser) {
  const chooser = m.status().choosingFirstPlayer;
  assert.equal(m.submit(cmd(m, chooser, 'chooseWhoGoesFirst', {playerId: 'p1'})).accepted, true);
  for (const p of ['p1', 'p2']) assert.equal(m.submit(cmd(m, p, 'alterHand', {cardsToMulligan: []})).accepted, true);
  assert.equal(m.submit(cmd(m, loser, 'concede')).accepted, true);
  return chooser;
}
disableAmbient();
const results = {};
try {
  // 1. Real secret-seeded matches with every ambient source disabled.
  const choosers = {p1: 0, p2: 0}, commitments = new Set(), initials = new Set(), finals = new Set();
  for (let i = 0; i < 40; i++) {
    const m = A.createQualificationMatch({players: ['p1', 'p2'], startTimestamp: 1000});
    assert.ok(Object.isFrozen(m)); assert.deepEqual(Object.keys(m).sort(), ['dispose', 'exportReplay', 'status', 'submit']);
    assert.deepEqual(Object.keys(m.status()).sort(), ['choosingFirstPlayer', 'ended', 'mode', 'revision', 'rewardEligible', 'seedCommitment', 'winner']);
    assert.throws(() => m.exportReplay(), /completed/);
    const liveViews = JSON.stringify([m, m.status()]);
    choosers[play(m, i % 2 ? 'p1' : 'p2')]++;
    const rec = m.exportReplay(), data = JSON.parse(rec.archive);
    assert.ok(!liveViews.includes(data.seed), 'live surface leaked seed');
    assert.equal(m.status().winner, i % 2 ? 'p2' : 'p1');
    assert.equal(A.verifyCompletedReplay(rec.archive, rec.digest).verified, true);
    commitments.add(data.seedCommitment); initials.add(data.initial.stateHash); finals.add(data.final.stateHash);
    m.dispose(); for (const f of ['status', 'exportReplay']) assert.throws(() => m[f](), /disposed/);
    assert.throws(() => m.submit(cmd({status: () => ({revision: 0})}, 'p1', 'concede')), /disposed/);
  }
  assert.equal(commitments.size, 40); assert.equal(initials.size, 40); assert.equal(finals.size, 40);
  assert.ok(choosers.p1 > 0 && choosers.p2 > 0, JSON.stringify(choosers));
  results.matches = 40; results.chooserCounts = choosers;
  // 2. Caller-selected entropy and non-plain options refused.
  const getter = {players: ['p1', 'p2']}; Object.defineProperty(getter, 'startTimestamp', {get: () => 0, enumerable: true});
  for (const bad of [{players: ['p1', 'p2'], startTimestamp: 0, seed: 'x'}, {players: ['p1', 'p2'], startTimestamp: 0, randomSource: {}}, getter,
    Object.assign(Object.create(null), {players: ['p1', 'p2'], startTimestamp: 0}), {players: ['p1', 'p1'], startTimestamp: 0}, {players: ['p1', 'p2'], startTimestamp: -1}])
    assert.throws(() => A.createQualificationMatch(bad), /Invalid/);
  // 3. Fixed-seed determinism (internal constructor), seed isolation and journaled rejections.
  const seed = Buffer.from(Array.from({length: 32}, (_, i) => 255 - i));
  const scripted = s => {
    n = 0; const m = R.createRecordedMatch({players: ['p1', 'p2'], startTimestamp: 1000}, s);
    assert.equal(m.submit(cmd(m, 'mallory', 'concede')).code, 'INVALID_ACTOR');
    assert.equal(m.submit({...cmd(m, 'p1', 'concede'), expectedRevision: 99}).code, 'STALE_REVISION');
    assert.throws(() => m.submit(cmd(m, 'p1', 'concede', {}, 5)), /timestamp/);
    play(m, 'p2'); const r = m.exportReplay(); m.dispose(); return r;
  };
  const a = scripted(seed), b = scripted(Buffer.from(seed)), c = scripted(Buffer.from(seed).reverse());
  assert.equal(a.archive, b.archive); assert.equal(a.digest, b.digest); assert.notEqual(a.archive, c.archive);
  const ad = JSON.parse(a.archive);
  assert.equal(ad.seed, seed.toString('hex')); assert.equal(ad.commands.length, 6);
  assert.deepEqual(ad.commands.slice(0, 2).map(r => [r.result.code, r.randomOutcomes.length]), [['INVALID_ACTOR', 0], ['STALE_REVISION', 0]]);
  assert.notEqual(ad.initial.stateHash, JSON.parse(c.archive).initial.stateHash);
  assert.ok(ad.initial.randomOutcomes.length > 0 && ad.commands.some(r => r.randomOutcomes.length > 0), 'shuffle/first-player outcomes recorded');
  assert.equal(A.verifyCompletedReplay(a.archive, a.digest).commands, 6);
  results.fixedSeedDeterministic = true;
  // 4. Tampering with a recomputed outer digest is rejected by reconstruction.
  const other = randomBytes(32);
  const edits = {
    consistentOtherSeed: r => { r.seed = other.toString('hex'); r.seedCommitment = createHash('sha256').update('server-match-seed-v1\0').update(ENGINE_REPLAY_IDENTITY).update(other).digest('hex'); },
    startTimestamp: r => { r.setup.startTimestamp++; }, swappedPlayers: r => { r.setup.players.reverse(); },
    commandOutcome: r => { const row = r.commands.find(x => x.randomOutcomes.length); row.randomOutcomes[0].index++; },
    duplicatedCommand: r => { r.commands.splice(3, 0, structuredClone(r.commands[3])); },
    rngVersion: r => { r.rngVersion = 'hmac-sha256-indexed-v2'; }, purpose: r => { r.purpose = 'ranked'; },
    rejectedMadeAccepted: r => { r.commands[0].result = {accepted: true, code: null}; },
  };
  for (const [name, edit] of Object.entries(edits)) {
    const r = JSON.parse(a.archive); edit(r); const t = JSON.stringify(r);
    assert.throws(() => A.verifyCompletedReplay(t, digest(t)), /Replay verification rejected/, name);
  }
  assert.throws(() => A.verifyCompletedReplay(a.archive, c.digest), /rejected/);
  assert.throws(() => A.verifyCompletedReplay(a.archive, a.digest.toUpperCase()), /rejected/);
  results.tamperCasesRejected = Object.keys(edits).length + 2;
  // 5. Interleaved concurrent matches stay independent and verifiable.
  const m1 = A.createQualificationMatch({players: ['p1', 'p2'], startTimestamp: 0}), m2 = A.createQualificationMatch({players: ['p1', 'p2'], startTimestamp: 0});
  for (const m of [m1, m2]) m.submit(cmd(m, m.status().choosingFirstPlayer, 'chooseWhoGoesFirst', {playerId: 'p2'}));
  for (const p of ['p2', 'p1']) for (const m of [m2, m1]) assert.equal(m.submit(cmd(m, p, 'alterHand', {cardsToMulligan: []})).accepted, true);
  for (const m of [m1, m2]) { m.submit(cmd(m, 'p2', 'concede')); const r = m.exportReplay(); assert.equal(A.verifyCompletedReplay(r.archive, r.digest).verified, true); m.dispose(); }
  results.interleaved = 2;
} finally { restoreAmbient(); }
// 6. Admission stays closed outside synthetic qualification.
const base = {asOf: '2026-10-12', mode: 'qualification', rulesVersion: 'synthetic-fixture', sets: ['TST'], rewards: false, hiddenState: false};
assert.equal(A.assessEngineAdmission(base).allowed, true);
for (const change of [{mode: 'ranked'}, {mode: 'advanced-sandbox'}, {rulesVersion: '2.3.0'}, {sets: ['TST', '014']}, {rewards: true}, {hiddenState: true}, {asOf: '2026-10-23'}].slice(0, 6))
  assert.equal(A.assessEngineAdmission({...base, ...change}).allowed, false, JSON.stringify(change));
assert.equal(A.ENGINE_QUALIFICATION.randomQualification, 'server_crypto_v1');
// 7. Internal modules are not reachable through the package exports map.
const sub = spawnSync(process.execPath, ['--input-type=module', '-e', "try{await import('@lorcana/engine-adapter/dist/replay.js');console.log('REACHABLE')}catch(e){console.log(e.code)}"], {cwd: 'packages/engine-adapter', encoding: 'utf8'});
assert.equal(sub.stdout.trim(), 'ERR_PACKAGE_PATH_NOT_EXPORTED', sub.stdout + sub.stderr);
console.log(JSON.stringify(results));
